from sqlalchemy import Boolean, CheckConstraint, Column, DateTime, ForeignKey, Integer, JSON, MetaData, Numeric, String, Table, UniqueConstraint
from sqlalchemy.types import Uuid

metadata=MetaData()
policies=Table("portfolio_policies",metadata,Column("policy_id",Uuid,primary_key=True),Column("version",String,nullable=False),Column("min_cash",Numeric,nullable=False),Column("max_instrument",Numeric,nullable=False),Column("market_caps",JSON,nullable=False),Column("industry_caps",JSON,nullable=False),Column("max_turnover",Numeric,nullable=False),Column("account_max_age_seconds",Integer,nullable=False),Column("tolerance",Numeric,nullable=False))
sleeves=Table("portfolio_sleeve_policies",metadata,Column("sleeve_id",Uuid,primary_key=True),Column("policy_id",Uuid,ForeignKey("portfolio_policies.policy_id"),nullable=False),Column("kind",String,nullable=False),Column("budget",Numeric,nullable=False),Column("required",Boolean,nullable=False),Column("priority",Integer,nullable=False),UniqueConstraint("policy_id","kind"))
targets=Table("target_portfolios",metadata,Column("target_id",Uuid,primary_key=True),Column("policy_id",Uuid,ForeignKey("portfolio_policies.policy_id"),nullable=False),Column("strategy_run_ids",JSON,nullable=False),Column("account_snapshot_id",Uuid,nullable=False),Column("built_at",DateTime(timezone=True),nullable=False),Column("cash_weight",Numeric,nullable=False),Column("input_hash",String,unique=True,nullable=False),Column("content_hash",String,nullable=False),CheckConstraint("cash_weight>=0 AND cash_weight<=1"))
weights=Table("target_weights",metadata,Column("weight_id",Uuid,primary_key=True),Column("target_id",Uuid,ForeignKey("target_portfolios.target_id"),nullable=False),Column("instrument_id",Uuid,nullable=False),Column("weight",Numeric,nullable=False),UniqueConstraint("target_id","instrument_id"),CheckConstraint("weight>=0 AND weight<=1"))
contributions=Table("target_contributions",metadata,Column("contribution_id",Uuid,primary_key=True),Column("target_id",Uuid,ForeignKey("target_portfolios.target_id"),nullable=False),Column("sleeve",String,nullable=False),Column("instrument_id",Uuid),Column("raw_weight",Numeric,nullable=False),Column("final_weight",Numeric,nullable=False),Column("cash_contribution",Numeric,nullable=False))
constraints=Table("constraint_results",metadata,Column("result_id",Uuid,primary_key=True),Column("target_id",Uuid,ForeignKey("target_portfolios.target_id"),nullable=False),Column("rule",String,nullable=False),Column("scope",String,nullable=False),Column("before",Numeric,nullable=False),Column("after",Numeric,nullable=False),Column("limit_value",Numeric,nullable=False),Column("binding",Boolean,nullable=False),Column("reason",String,nullable=False),Column("severity",String,nullable=False))
deltas=Table("rebalance_deltas",metadata,Column("delta_id",Uuid,primary_key=True),Column("target_id",Uuid,ForeignKey("target_portfolios.target_id"),nullable=False),Column("instrument_id",Uuid,nullable=False),Column("current_weight",Numeric,nullable=False),Column("target_weight",Numeric,nullable=False),Column("delta",Numeric,nullable=False),UniqueConstraint("target_id","instrument_id"))
events=Table("portfolio_events",metadata,Column("event_id",Uuid,primary_key=True),Column("event_type",String,nullable=False),Column("target_id",Uuid,nullable=False),Column("occurred_at",DateTime(timezone=True),nullable=False),Column("reasons",JSON,nullable=False),Column("input_hash",String))
